-- 562: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 9 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_562_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_562_guard;
INSERT INTO _migration_562_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_033' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The total way of life of a people — including their language, food, dress, beliefs and values — is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Culture","B. Climate","C. Population","D. Governance"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Culture is the learned, shared way of life of a group, covering both material objects and non-material elements such as language and beliefs. Climate describes weather patterns, population describes numbers of people, and governance is only one narrow institution within a way of life. Therefore the correct answer is A: Culture.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_033' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_562_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_034' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a traditional festival celebrated in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Christmas","B. Homowo of the Ga people","C. Eid al-Fitr","D. Easter"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Homowo — the Ga “hooting at hunger” harvest festival — is an indigenous Ghanaian festival, like Aboakyir of the Effutu and Odwira of the Akan. Christmas, Eid al-Fitr and Easter are Christian and Islamic festivals of foreign origin, not traditional Ghanaian festivals. Therefore the correct answer is B: Homowo of the Ga people.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_034' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_562_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_035' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The process by which countries and peoples of the world become increasingly interconnected through trade, technology and communication is called...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Urbanization","B. Industrialization","C. Globalization","D. Nationalization"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Globalization is the growing integration of economies, cultures and communication across borders. Urbanization is the growth of towns, industrialization is the spread of manufacturing industry, and nationalization is state takeover of private assets — none of them describes worldwide interconnectedness. Therefore the correct answer is C: Globalization.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_035' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_562_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_036' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is an aspect of Ghana’s material culture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Respect for elders","B. The Twi language","C. Belief in the Supreme Being","D. Kente cloth and carved traditional stools"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Material culture consists of tangible, physical objects a society makes — cloth, stools, pottery and tools. Respect for elders, language and religious belief are intangible, non-material culture: they exist as values, symbols and ideas rather than objects. Therefore the correct answer is D: Kente cloth and carved traditional stools.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_036' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
